  (`word`, `phonetic`, `translation`, `pos`, `example`, `example_translation`, `level`, `usage_count`)
VALUES
('dormitory', '/''dɒ:mitәri/', 'n. 宿舍', 'n', 'I left the notes in the dormitory. I''ll go back and get them now.', '我把笔记放在宿舍了，现在回去拿。', 'CET4', 0),
('dose', '/dәus/', 'n. 剂量, 服用量 vt. 给药, (用药)医治 vi. 服药', 'n', 'Never exceed the recommended dose of painkillers', '服用止痛药不可超过建议的剂量。', 'CET4', 0),
('dot', '/dɒt/', 'n. 点, 圆点, 小数点, 小东西, 嫁妆 vt. 作小点记号, 加小点于 vi. 打上点 [计] 点', 'n', 'The general meeting began at 9 am on the dot.', '总会在九点整开始了。', 'CET4', 0),
('doubt', '/daut/', 'n. 怀疑, 疑惑 v. 怀疑, 不信', 'n', 'People who love doubt nothing, or doubt everything.', '喜欢的人什么都不怀疑，或什么都疑神疑鬼。', 'CET4', 0),
('doubtful', '/''dautful/', 'a. 可疑的, 疑心的, 不明确的 [法] 怀疑的, 有疑问的, 未确的', 'adj', 'Mrs. Harris is very doubtful about her son''s future.', '夏里斯太太对她儿子的前途没有甚么信心。', 'CET4', 0),
('doubtless', '/''dautlis/', 'a. 无疑的, 确定的 adv. 无疑地, 确定地', 'adj', 'Doubtless there would be lots of rumours.', '无疑会谣言四起。', 'CET4', 0),
('downstairs', '/''daun''stєәz/', 'n. 楼下 a. 楼下的 adv. 在楼下', 'n', 'Ann came downstairs.', '安下楼来了。', 'CET4', 0),
('downward', '/''daunwәd/', 'a. 向下的', 'adj', 'a gentle downward slope', '缓坡', 'CET4', 0),
('dozen', '/''dʌzn/', 'n. 打, 十二个 a. 一打的', 'n', 'I bought a dozen pencils today.', '我今天买了一打铅笔。', 'CET4', 0),
('draft', '/dræft. drɑ:ft/', 'n. 气流, 草稿, 汇票, 草案 vt. 起草, 征兵 [计] 草稿', 'n', 'I am writing a draft of the speech.', '我在写演讲的草稿。', 'CET4', 0),
('drag', '/dræg/', 'n. 拖, 拖累 v. 拖累, 拖拉, 沉重缓慢地走, 拖动 [计] 拖动', 'n', 'Inge managed to drag the table into the kitchen.', '英奇费了很大劲把桌子拖进厨房里。', 'CET4', 0),
('dragon', '/''drægәn/', 'n. 龙, 凶暴的人 [法] 凶恶的人, 凶恶严厉的监护人', 'n', 'The dragon is an imaginary creature.', '龙是人幻想出来的生物。', 'CET4', 0),
('drain', '/drein/', 'n. 排水沟, 消耗, 排水 vt. 排出, 喝光, 耗尽 vi. 排水, 流干', 'n', 'The swimming pool is drained and cleaned every winter.', '每年冬天这座游泳池都要排干清洗。', 'CET4', 0),
('drama', '/''drɑ:mә/', 'n. 戏剧, 戏剧艺术', 'n', 'Bob is in the drama club.', '鲍伯在话剧社。', 'CET4', 0),
('dramatic', '/drә''mætik/', 'a. 戏剧性的, 生动的', 'adj', 'the amateur dramatic society', '业余剧团', 'CET4', 0),
('drawer', '/''drɒ:ә/', 'n. 抽屉, 开票人 [计] 抽屉', 'n', 'The desk drawer is open.', '办公桌的抽屉是开着的。', 'CET4', 0),
('drawing', '/''drɒ:iŋ/', 'n. 图画, 制图, 拉 [计] 绘图', 'n', 'I''m busy because the finals are drawing on.', '快要考期末试了，所以我很忙。', 'CET4', 0),
('dread', '/dred/', 'n. 恐惧, 可怕的人(或事) a. 可怕的, 可怖的 v. 恐惧, 害怕', 'n', 'Why do you think animals dread fire?', '你觉得动物为什么会怕火呢？', 'CET4', 0),
('dream', '/dri:m/', 'n. 梦, 空想, 愿望 v. 做梦, 想象, 梦想', 'n', 'How could I be a robot? Robots don''t dream.', '我怎么可能是机器人呢？机器人不会做梦。', 'CET4', 0),
('drift', '/drift/', 'n. 漂流物, 漂流, 动向 v. (使)漂流', 'n', 'Many people drift through life without a purpose.', '许多人毫无目的地随波逐流。', 'CET4', 0),
('drill', '/dril/', 'n. 钻孔机, 钻子, 播种机, 粗斜纹布 v. 训练, 钻孔', 'n', 'We had a fire drill yesterday.', '我们昨天进行了火警演习。', 'CET4', 0),
('drip', '/drip/', 'n. 水滴 v. (使)滴下', 'n', 'The tap’s dripping .', '水龙头在滴水。', 'CET4', 0),
('drop', '/drɒp/', 'n. 滴, 微量, 落下, 空投 vi. 放下, 掉下, 下降 vt. 使滴下, 放下, 丢失, 遗漏 [计] 投入, 投入点, 接入点, 分接点', 'n', 'Please drop in at my house on your way home.', '你回家途中顺道来看看我吧。', 'CET4', 0),
('drought', '/draut/', 'n. 干旱, 缺乏', 'n', 'Last year the region was visited by the worst drought in 60 years.', '去年那个地区遭受了60年来最严重的干旱。', 'CET4', 0),
('drown', '/draun/', 'vi. 淹死 vt. 把...淹死, 淹没', 'vi', 'I have to wear earplugs to drown out all the noise from the construction site next door.', '我不得不戴耳塞来阻隔旁边建筑工地的所有噪音。', 'CET4', 0),
('drug', '/drʌg/', 'n. 药, 麻药, 麻醉药 vi. 吸毒 vt. 使服麻醉药, 使麻木', 'n', 'The drug problem is international.', '毒品是国际性的问题。', 'CET4', 0),
('drum', '/drʌm/', 'n. 鼓, 鼓声 vi. 击鼓, 作鼓声 vt. 打鼓奏出 [计] 磁鼓', 'n', 'Jim likes to play the drum.', '吉姆喜欢打鼓。', 'CET4', 0),
('drunk', '/drʌŋk/', 'a. 喝醉了的 drink的过去式', 'adj', 'You''re too drunk to drive.', '你酒喝得太醉了不能开车。', 'CET4', 0),
('duck', '/dʌk/', 'n. 鸭子 vi. 没入水中, 闪避 vt. 猛按...入水, 躲避', 'n', 'It looks like a duck.', '它看起来像一只鸭子。', 'CET4', 0),
('due', '/dju:/', 'n. 应得的东西, 应付款 a. 到期的, 应得的, 应付的, 约定的', 'n', 'The school''s closure was due to the snow.', '停课是因为下雪。', 'CET4', 0),
('dull', '/dʌl/', 'a. 钝的, 无趣的, 呆滞的, 阴暗的 vt. 使迟钝, 使阴暗, 缓和 vi. 变迟钝, 减少', 'adj', 'Were it not for music, the world would be a dull place.', '如果没有了音乐，这个世界就会变得十分沉闷。', 'CET4', 0),
('dumb', '/dʌm/', 'a. 哑的, 不说话的, 无声音的 [医] 哑的', 'adj', 'I''m so dumb... I''m trying to explain things to you that I don''t understand myself.', '我太愚蠢了...我竟然试着给你解释我自己都不懂的东西。', 'CET4', 0),
('dump', '/dʌmp/', 'n. 垃圾场 vt. 倾倒, 倾销 vi. 倒垃圾, 倾销商品 [计] 转出; 转储; 倾卸; 切断电源', 'n', 'Is Tom going to dump Mary?', '汤姆要甩了玛丽吗？', 'CET4', 0),
